#include "tiling_base/tiling_base.h"
#include "tiling_base/tiling_templates_registry.h"
#include "log/log.h"
#include "kernel_tiling/kernel_tiling.h"

namespace optiling {
static ge::graphStatus TilingForSinkhorn(gert::TilingContext *context)
{
    return Ops::Transformer::OpTiling::TilingRegistry::GetInstance().DoTilingImpl(context);
}

static ge::graphStatus TilingPrepareForSinkhorn(gert::TilingParseContext *context)
{
    (void)context;
    return ge::GRAPH_SUCCESS;
}

IMPL_OP_OPTILING(ManifoldConstrainedHyperConnectionSinkhornEnhance)
    .Tiling(TilingForSinkhorn)
    .TilingParse<SinkhornCompileInfo>(TilingPrepareForSinkhorn);

