23	// Helper function for ceiling division
24	inline int64_t CeilDiv(int64_t a, int64_t b)
25	{
26	    if (b == 0) {
27	        return 0;
28	    }
29	    return (a + b - 1) / b;
30	}
31	
32	inline int64_t AlignDown(int64_t a, int64_t b)
33	{
34	    if (b == 0) {
35	        return 0;
36	    }
37	    return a / b * b;
38	}
39	
40	inline int64_t AlignUp(int64_t a, int64_t b)
41	{
42	    if (b == 0) {
43	        return 0;
44	    }
45	    return CeilDiv(a, b) * b;
46	}
