/*!
 * \file manifold_constrained_hyper_connection_sinkhorn_enhance.cpp
 * \brief
 */
#include "kernel_operator.h"
#include "kernel_tiling/kernel_tiling.h"
#include "manifold_constrained_hyper_connection_sinkhorn_enhance_generalized.h"
#include "manifold_constrained_hyper_connection_sinkhorn_enhance_generalized_infer.h"

using namespace AscendC;
using namespace ManifoldConstrainedHyperConnectionSinkhornEnhance;

extern "C" __global__ __aicore__ void manifold_constrained_hyper_connection_sinkhorn_enhance(
    GM_ADDR x, GM_ADDR output, GM_ADDR normOut, GM_ADDR sumOut, GM_ADDR workspace, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIV_ONLY);

    if (g_coreType == AIC) {
        return;
    }
    GET_TILING_DATA(tilingData, tiling);

    if (workspace == nullptr) {
        return;
    }

    GM_ADDR userWS = GetUserWorkspace(workspace);
    if (userWS == nullptr) {
        return;
    }

    TPipe tPipe;
    if (TILING_KEY_IS(1)) {
        // 推理路径（out_flag=0）：DataCopyPad，无 normOut/sumOut
        switch (tilingData.nNum) {
            case 4: {
                ManifoldConstrainedHyperConnectionSinkhornEnhanceInfer::SinkhornInferGeneralized<DTYPE_X, 4> op;
                op.Init(x, output, userWS, &tilingData, &tPipe);
                op.Process();
                break;
            }
            default: {
                ManifoldConstrainedHyperConnectionSinkhornEnhanceInfer::SinkhornInferGeneralized<DTYPE_X, 0> op;
                op.Init(x, output, userWS, &tilingData, &tPipe);
                op.Process();
                break;
            }
        }
    }
    if (TILING_KEY_IS(0)) {
        // 训练路径（out_flag=1）：Transpose，输出 normOut/sumOut（保持原有行为）
        SinkhornGeneralized<DTYPE_X> op;
        op.Init(x, output, normOut, sumOut, userWS, &tilingData, &tPipe);
        op.Process();
    }
    tPipe.Destroy();
}

