23	
24	constexpr int64_t BLOCK_BYTES = 32;
25	constexpr int64_t DOUBULE_BUFFER = 2;
26	
27	__aicore__ inline int64_t Ceil(int64_t a, int64_t b)
28	{
29	    if (b == 0) {
30	        return 0;
31	    }
32	    return (a + b - 1) / b;
33	}
34	
35	__aicore__ inline int64_t Min(int64_t a, int64_t b)
36	{
37	    return (a < b) ? a : b;
38	}
39	
40	__aicore__ inline int64_t Align(int64_t elementNum, int64_t bytes)
41	{
42	    if (bytes == 0) {
43	        return 0;
44	    }
45	    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES / bytes;
46	}
47	
48	__aicore__ inline int64_t AlignBytes(int64_t elementNum, int64_t bytes)
49	{
50	    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES;
51	}
52	
53	template <typename T> class SinkhornGeneralized {
54	  public:
55	    __aicore__ inline SinkhornGeneralized(){};
56	    __aicore__ inline void Init(GM_ADDR x,
57	                                GM_ADDR output,
58	                                GM_ADDR normOut,
59	                                GM_ADDR sumOut,
60	                                GM_ADDR workspace,
61	                                const SinkhornTilingData *tilingData,
62	                                TPipe *tPipe);
63	    __aicore__ inline void Process();
64	
65	  private:
66	    __aicore__ inline void CopyInX(int64_t offset);
67	    __aicore__ inline void CopyOut(int64_t offset);
68	    __aicore__ inline void TransposeXIn(LocalTensor<T> xLocal);
69	    __aicore__ inline void TransposeXOut();
70	    __aicore__ inline void InitialSoftmax();
71	    __aicore__ inline void ColNormalize(LocalTensor<uint8_t> calReduceTensor);
72	    __aicore__ inline void RowNormalize(LocalTensor<uint8_t> calReduceTensor);
73	    __aicore__ inline void CopyOutNormOut(int64_t offset);
74	    __aicore__ inline void CopyOutSumOut(int64_t offset);
75	
76	  private:
77	    TPipe *pipe_;
78	    GlobalTensor<T> xGm_;
79	    GlobalTensor<T> outputGm_;
80	    GlobalTensor<T> normOutGm_;
81	    GlobalTensor<T> sumOutGm_;
82	
83	    TQue<QuePosition::VECIN, 1> xInQueue_;
84	    TQue<QuePosition::VECOUT, 1> outputQueue_;
85	    TQue<QuePosition::VECOUT, 2> normOutQueue_;
86	    TQue<QuePosition::VECOUT, 2> sumOutQueue_;
87	    TBuf<QuePosition::VECCALC> tmpBuf_, maxBuf_, sumBuf_, transposeBuf_; // 中间计算缓存
88	
89	    int64_t outFlag_;
90	    float eps_;
91	    int64_t numIters_;
92	
93	    int64_t totalLength_;
94	    int64_t n_;
95	    int64_t needCoreNum_;
96	    int64_t tAlign_;
97	
98	    // 核间切分
99	    int64_t perCoreElements_;
100	    int64_t lastCoreElements_;
101	    int64_t blockIdx_;
102	
103	    // 核内切分
104	    int64_t perCoreLoops_;
105	    int64_t perCorePerLoopElements_;
106	    int64_t perCoreLastLoopElements_;
107	    int64_t lastCoreLoops_;
108	    int64_t lastCorePerLoopElements_;
109	    int64_t lastCoreLastLoopElements_;
110	
111	    // 当前核的tiling策略
112	    int64_t currentCoreElements_;
113	    int64_t currentCoreloops_;
114	    int64_t currentCorePerLoopElements_;
115	    int64_t currentCoreLastLoopElements_;
116	
117	    int64_t currentLoopElements_;
118	};
119	
120	template <typename T>
121	__aicore__ inline void SinkhornGeneralized<T>::Init(GM_ADDR x,
122	                                                    GM_ADDR output,
123	                                                    GM_ADDR normOut,
124	                                                    GM_ADDR sumOut,
125	                                                    GM_ADDR workspace,
126	                                                    const SinkhornTilingData *tilingData,
127	                                                    TPipe *tPipe)
128	{
129	    pipe_ = tPipe;
130	
131	    // Get tiling data
132	    outFlag_ = tilingData->outFlag;
133	    eps_ = tilingData->eps;
134	    numIters_ = tilingData->numIters;
135	    totalLength_ = tilingData->totalLength;
136	    n_ = tilingData->nNum;
137	
138	    needCoreNum_ = tilingData->needCoreNum;
139	    perCoreElements_ = tilingData->perCoreElements;
140	    lastCoreElements_ = tilingData->lastCoreElements;
141	    perCoreLoops_ = tilingData->perCoreLoops;
142	    perCorePerLoopElements_ = tilingData->perCorePerLoopElements;
143	    perCoreLastLoopElements_ = tilingData->perCoreLastLoopElements;
144	    lastCoreLoops_ = tilingData->lastCoreLoops;
145	    lastCorePerLoopElements_ = tilingData->lastCorePerLoopElements;
146	    lastCoreLastLoopElements_ = tilingData->lastCoreLastLoopElements;
147	
148	    blockIdx_ = GetBlockIdx();
149	    currentCoreElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreElements_ : lastCoreElements_;
150	    currentCoreloops_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreLoops_ : lastCoreLoops_;
151	    currentCorePerLoopElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCorePerLoopElements_ : lastCorePerLoopElements_;
152	    currentCoreLastLoopElements_ =
153	        (blockIdx_ < needCoreNum_ - 1) ? perCoreLastLoopElements_ : lastCoreLastLoopElements_;
154	
155	    tAlign_ = Align(perCorePerLoopElements_, sizeof(float)); // 32B对齐
156	
157	    // Set global tensors
158	    int64_t Offset = blockIdx_ * perCoreElements_ * n_ * n_;
159	    xGm_.SetGlobalBuffer((__gm__ T *)x + Offset, currentCoreElements_ * n_ * n_);
160	    outputGm_.SetGlobalBuffer((__gm__ T *)output + Offset, currentCoreElements_ * n_ * n_);
161	    normOutGm_.SetGlobalBuffer((__gm__ T *)normOut);
162	    sumOutGm_.SetGlobalBuffer((__gm__ T *)sumOut);
163	
164	    // Initialize pipe (placeholder)
165	    // (5 tnn + 4 tn) * 4 + 1024n B
166	    pipe_->InitBuffer(xInQueue_, 1, tAlign_ * n_ * n_ * sizeof(T)); // t * n * n
167	    pipe_->InitBuffer(outputQueue_, 1, tAlign_ * n_ * n_ * sizeof(T)); // t * n * n
168	
169	    pipe_->InitBuffer(maxBuf_, tAlign_ * n_ * sizeof(T)); // t * n
170	    pipe_->InitBuffer(sumBuf_, tAlign_ * n_ * sizeof(T)); // t * n
171	    pipe_->InitBuffer(transposeBuf_, tAlign_ * n_ * n_ * sizeof(T)); // t * n * n
172	    pipe_->InitBuffer(tmpBuf_, (n_ * n_ * 2 + 1) * 16 * 32); // (2n*n+1) * 16 * 32 B
173	
174	    if (outFlag_) {
175	        pipe_->InitBuffer(normOutQueue_, DOUBULE_BUFFER, tAlign_ * n_ * n_ * sizeof(T)); // 2 * t * n * n
176	        pipe_->InitBuffer(sumOutQueue_, DOUBULE_BUFFER, tAlign_ * n_ * sizeof(T)); // 2 * t * n
177	    }
178	}
179	
180	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::Process()
181	{
182	    if (blockIdx_ >= needCoreNum_) {
183	        return;
184	    }
185	    // 一次归一化产生的normOut矩阵大小
186	    int64_t normOutBlockLen = n_ * n_ * totalLength_;
187	    // 一次归一化产生的sumOut矩阵大小
188	    int64_t sumOutBlockLen = n_ * totalLength_;
189	
190	    // Main processing loop (placeholder)
191	    for (int i = 0; i < currentCoreloops_; ++i) {
192	        // 当前核当前loop处理的token数
193	        currentLoopElements_ =
194	            (i == currentCoreloops_ - 1) ? currentCoreLastLoopElements_ : currentCorePerLoopElements_;
195	        // 核内GM核内偏移, 初始化时已增加核间偏移
196	        int64_t offset = i * currentCorePerLoopElements_ * n_ * n_;
197	        // normOut与sumOut在GM上最后一个维度上t的偏移
198	        int64_t tOffset = blockIdx_ * perCoreElements_ + i * currentCorePerLoopElements_;
199	        int64_t normOffset = 0;
200	        int64_t sumOffset = 0;
201	
202	        // 步骤1：数据拷入+转置
203	        CopyInX(offset);
204	        LocalTensor<T> xLocal = xInQueue_.DeQue<T>();
205	        TransposeXIn(xLocal);
206	        LocalTensor<uint8_t> calReduceTensor = xLocal.template ReinterpretCast<uint8_t>();
207	        // 步骤2：行初始归一化(softmax)
208	        InitialSoftmax();
209	        if (outFlag_) {
210	            normOffset = tOffset;
211	            CopyOutNormOut(normOffset);
212	        }
213	
214	        // 步骤3：列初始归一化
215	        ColNormalize(calReduceTensor);
216	        if (outFlag_) {
217	            normOffset = normOutBlockLen + tOffset;
218	            sumOffset = sumOutBlockLen + tOffset;
219	            CopyOutNormOut(normOffset);
220	            CopyOutSumOut(sumOffset);
221	        }
222	
223	        // 步骤4：迭代行列交替归一化
224	        for (uint32_t iter = 1; iter < numIters_; ++iter) {
225	            int64_t rowOffset = 2 * iter;
226	            int64_t colOffset = 2 * iter + 1;
227	            // 行归一化
228	            RowNormalize(calReduceTensor);
229	            if (outFlag_) {
230	                normOffset = rowOffset * normOutBlockLen + tOffset;
231	                sumOffset = rowOffset * sumOutBlockLen + tOffset;
232	                CopyOutNormOut(normOffset);
233	                CopyOutSumOut(sumOffset);
234	            }
235	            // 列归一化
236	            ColNormalize(calReduceTensor);
237	            if (outFlag_) {
238	                normOffset = colOffset * normOutBlockLen + tOffset;
239	                sumOffset = colOffset * sumOutBlockLen + tOffset;
240	                CopyOutNormOut(normOffset);
241	                CopyOutSumOut(sumOffset);
242	            }
243	        }
244	        xInQueue_.FreeTensor(xLocal);
245	        // 步骤5：转置+数据拷出
246	        TransposeXOut();
247	        CopyOut(offset);
248	    }
249	}
250	
251	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyInX(int64_t offset)
252	{
253	    LocalTensor<T> xLocal = xInQueue_.AllocTensor<T>();
254	
255	    DataCopyExtParams dataCopyParams{
256	        static_cast<uint16_t>(1), static_cast<uint32_t>(currentLoopElements_ * n_ * n_ * sizeof(T)), 0, 0, 0};
257	    DataCopyPadExtParams<T> dataCopyPadParams{false, 0, 0, 0};
258	    DataCopyPad(xLocal, xGm_[offset], dataCopyParams, dataCopyPadParams);
259	    xInQueue_.EnQue(xLocal);
260	}
261	
262	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::TransposeXIn(LocalTensor<T> xLocal)
263	{
264	    // [t, n, n] 转换为[n, n, t]
265	
266	    LocalTensor<T> xTranspose = transposeBuf_.Get<T>();
267	
268	    LocalTensor<uint8_t> sharedBuffer = tmpBuf_.Get<uint8_t>();
269	
270	    TransposeParamsExt transposeParams;
271	    transposeParams.nSize = 1;
272	    transposeParams.cSize = n_ * n_;
273	    transposeParams.hSize = 1;
274	    transposeParams.wSize = tAlign_;
275	    transposeParams.transposeType = TransposeType::TRANSPOSE_NHWC2NCHW;
276	    Transpose(xTranspose, xLocal, sharedBuffer, transposeParams);
277	    PipeBarrier<PIPE_V>();
278	}
279	
280	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::TransposeXOut()
281	{
282	    // [n, n, t] 转换为[t, n, n]
283	    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
284	    LocalTensor<T> xTranspose = outputQueue_.AllocTensor<T>();
285	
286	    LocalTensor<uint8_t> sharedBuffer = tmpBuf_.Get<uint8_t>();
287	
288	    TransposeParamsExt transposeParams;
289	    transposeParams.nSize = 1;
290	    transposeParams.cSize = n_ * n_;
291	    transposeParams.hSize = 1;
292	    transposeParams.wSize = tAlign_;
293	    transposeParams.transposeType = TransposeType::TRANSPOSE_NCHW2NHWC;
294	    Transpose(xTranspose, xLocal, sharedBuffer, transposeParams);
295	
296	    PipeBarrier<PIPE_V>();
297	    outputQueue_.EnQue(xTranspose);
298	}
299	
300	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::InitialSoftmax()
301	{
302	    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
303	    LocalTensor<T> maxLocal = maxBuf_.Get<T>();
304	    LocalTensor<T> sumLocal = sumBuf_.Get<T>();
305	    LocalTensor<T> tmpLocal = tmpBuf_.Get<T>();
306	    int64_t nt = tAlign_ * n_;
307	    Duplicate(sumLocal, (T)(0), nt);
308	    PipeBarrier<PIPE_V>();
309	    for (uint32_t i = 0; i < n_; ++i) {
310	        // 对第i列的所有行j（j=0到N-1），找到每个批次的最大值
311	        uint32_t colOffset = i * n_ * tAlign_;
312	        uint32_t colMaxSumOffset = i * tAlign_;
313	
314	        // 初始化最大值为第一行的值
315	        Max(maxLocal[colMaxSumOffset], xLocal[colOffset], xLocal[colOffset + tAlign_], tAlign_);
316	        PipeBarrier<PIPE_V>();
317	        // 遍历剩余行，更新最大值
318	        for (uint32_t j = 2; j < n_; ++j) {
319	            uint32_t rowOffset = colOffset + j * tAlign_;
320	            // 使用Max函数进行向量化最大值计算
321	            Max(maxLocal[colMaxSumOffset], maxLocal[colMaxSumOffset], xLocal[rowOffset], tAlign_);
322	        }
323	
324	        for (uint32_t j = 0; j < n_; ++j) {
325	            uint32_t rowOffset = colOffset + j * tAlign_;
326	            // 计算 x - max
327	            Sub(tmpLocal, xLocal[rowOffset], maxLocal[colMaxSumOffset], tAlign_);
328	            PipeBarrier<PIPE_V>();
329	            // 计算 exp(x - max)
330	            Exp(tmpLocal, tmpLocal, tAlign_);
331	            PipeBarrier<PIPE_V>();
332	            // 累加到和
333	            Add(sumLocal[colMaxSumOffset], sumLocal[colMaxSumOffset], tmpLocal, tAlign_);
334	            // 将exp值写回数据
335	            DataCopy(xLocal[rowOffset], tmpLocal, tAlign_);
336	        }
337	
338	        // 对第i列的所有行j，计算 exp / (sum + eps)
339	        for (uint32_t j = 0; j < n_; ++j) {
340	            uint32_t rowOffset = colOffset + j * tAlign_;
341	            Div(xLocal[rowOffset], xLocal[rowOffset], sumLocal[colMaxSumOffset], tAlign_);
342	        }
343	    }
344	    PipeBarrier<PIPE_V>();
345	    if (outFlag_) {
346	        LocalTensor<T> normLocal = normOutQueue_.AllocTensor<T>();
347	        DataCopy(normLocal, xLocal, tAlign_ * n_ * n_);
348	        normOutQueue_.EnQue(normLocal);
349	    }
350	    PipeBarrier<PIPE_V>();
351	    Adds(xLocal, xLocal, eps_, n_ * n_ * tAlign_);
352	    PipeBarrier<PIPE_V>();
353	}
354	
355	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::ColNormalize(LocalTensor<uint8_t> calReduceTensor)
356	{
357	    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
358	    LocalTensor<T> sumLocal = sumBuf_.Get<T>();
359	    int64_t nt = tAlign_ * n_;
360	
361	    uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_ * n_)};
362	    AscendC::ReduceSum<float, Pattern::Reduce::RA, false>(sumLocal, xLocal, calReduceTensor, shape, true);
363	    PipeBarrier<PIPE_V>();
364	    Adds(sumLocal, sumLocal, eps_, nt);
365	    PipeBarrier<PIPE_V>();
366	    for (uint32_t i = 0; i < n_; ++i) {
367	        Div(xLocal[i * nt], xLocal[i * nt], sumLocal, nt);
368	    }
369	    PipeBarrier<PIPE_V>();
370	    if (outFlag_) {
371	        LocalTensor<T> normLocal = normOutQueue_.AllocTensor<T>();
372	        LocalTensor<T> sumOutLocal = sumOutQueue_.AllocTensor<T>();
373	        DataCopy(normLocal, xLocal, tAlign_ * n_ * n_);
374	        DataCopy(sumOutLocal, sumLocal, tAlign_ * n_);
375	        normOutQueue_.EnQue(normLocal);
376	        sumOutQueue_.EnQue(sumOutLocal);
377	    }
378	}
379	
380	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::RowNormalize(LocalTensor<uint8_t> calReduceTensor)
381	{
382	    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
383	    LocalTensor<T> sumLocal = sumBuf_.Get<T>();
384	    int64_t nt = tAlign_ * n_;
385	
386	    for (uint32_t i = 0; i < n_; ++i) {
387	        uint32_t colMaxSumOffset = i * tAlign_;
388	        uint32_t rowOffset = i * n_ * tAlign_;
389	        uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_)};
390	
391	        ReduceSum<float, Pattern::Reduce::RA, false>(
392	            sumLocal[colMaxSumOffset], xLocal[rowOffset], calReduceTensor, shape, true);
393	        // 遍历所有列，累加第i行的值
394	        PipeBarrier<PIPE_V>();
395	        Adds(sumLocal[colMaxSumOffset], sumLocal[colMaxSumOffset], eps_, tAlign_);
396	        PipeBarrier<PIPE_V>();
397	        // 对第i行的所有列j，计算 value / (sum + eps)
398	        for (uint32_t j = 0; j < n_; ++j) {
399	            uint32_t colOffset = rowOffset + j * tAlign_;
400	            // value / (sum + eps)
401	            Div(xLocal[colOffset], xLocal[colOffset], sumLocal[colMaxSumOffset], tAlign_);
402	        }
403	    }
404	    PipeBarrier<PIPE_V>();
405	    if (outFlag_) {
406	        LocalTensor<T> normLocal = normOutQueue_.AllocTensor<T>();
407	        LocalTensor<T> sumOutLocal = sumOutQueue_.AllocTensor<T>();
408	        DataCopy(normLocal, xLocal, tAlign_ * n_ * n_);
409	        DataCopy(sumOutLocal, sumLocal, tAlign_ * n_);
410	        normOutQueue_.EnQue(normLocal);
411	        sumOutQueue_.EnQue(sumOutLocal);
412	    }
413	}
414	
415	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyOutNormOut(int64_t normOffset)
416	{
417	    // srcStride，前一个数据块的尾与后一个数据块的头， GM上单位为字节
418	    // dstStride, 前一个数据块的尾与后一个数据块的头， UB上单位为32B
419	    LocalTensor<T> normLocal = normOutQueue_.DeQue<T>();
420	
421	    uint16_t blockCount = static_cast<uint16_t>(n_ * n_);
422	    uint32_t blockLen = static_cast<uint32_t>(currentLoopElements_ * sizeof(T));
423	    uint32_t srcStride = static_cast<uint32_t>((tAlign_ - currentLoopElements_) * sizeof(T) / BLOCK_BYTES);
424	    uint32_t dstStride = static_cast<uint32_t>((totalLength_ - currentLoopElements_) * sizeof(T));
425	    DataCopyExtParams dataCopyParams{blockCount, blockLen, srcStride, dstStride, 0};
426	
427	    DataCopyPad(normOutGm_[normOffset], normLocal, dataCopyParams);
428	    normOutQueue_.FreeTensor(normLocal);
429	}
430	
431	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyOutSumOut(int64_t sumOffset)
432	{
433	    LocalTensor<T> sumLocal = sumOutQueue_.DeQue<T>();
434	    uint16_t blockCount = static_cast<uint16_t>(n_);
435	    uint32_t blockLen = static_cast<uint32_t>(currentLoopElements_ * sizeof(T));
436	    uint32_t srcStride = static_cast<uint32_t>((tAlign_ - currentLoopElements_) * sizeof(T) / BLOCK_BYTES);
437	    uint32_t dstStride = static_cast<uint32_t>((totalLength_ - currentLoopElements_) * sizeof(T));
438	    DataCopyExtParams dataCopyParams{blockCount, blockLen, srcStride, dstStride, 0};
439	
440	    DataCopyPad(sumOutGm_[sumOffset], sumLocal, dataCopyParams);
441	    sumOutQueue_.FreeTensor(sumLocal);
442	}
443	
444	template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyOut(int64_t offset)
445	{
446	    LocalTensor<T> xLocal = outputQueue_.DeQue<T>();
447	    DataCopyExtParams copyParams{
448	        static_cast<uint16_t>(1), static_cast<uint32_t>(currentLoopElements_ * n_ * n_ * sizeof(T)), 0, 0, 0};
449	    DataCopyPad(outputGm_[offset], xLocal, copyParams);
450	    outputQueue_.FreeTensor(xLocal);
451	}
452	
453	} // namespace ManifoldConstrainedHyperConnectionSinkhornEnhance
454	
455	#endif // SINKHORN_GENERALIZED_H
