/*!
 * \file manifold_constrained_hyper_connection_sinkhorn_enhance_generalized.h
 * \brief
 */
#ifndef SINKHORN_GENERALIZED_H
#define SINKHORN_GENERALIZED_H
#include "kernel_operator.h"
#include "kernel_utils.h"
#include "kernel_tiling/kernel_tiling.h"

namespace ManifoldConstrainedHyperConnectionSinkhornEnhance {
using namespace AscendC;

constexpr int64_t BLOCK_BYTES = 32;
constexpr int64_t DOUBULE_BUFFER = 2;

__aicore__ inline int64_t Ceil(int64_t a, int64_t b)
{
    if (b == 0) {
        return 0;
    }
    return (a + b - 1) / b;
}

__aicore__ inline int64_t Min(int64_t a, int64_t b)
{
    return (a < b) ? a : b;
}

__aicore__ inline int64_t Align(int64_t elementNum, int64_t bytes)
{
    if (bytes == 0) {
        return 0;
    }
    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES / bytes;
}

__aicore__ inline int64_t AlignBytes(int64_t elementNum, int64_t bytes)
{
    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES;
}

template <typename T> class SinkhornGeneralized {
  public:
    __aicore__ inline SinkhornGeneralized(){};
    __aicore__ inline void Init(GM_ADDR x,
                                GM_ADDR output,
                                GM_ADDR normOut,
                                GM_ADDR sumOut,
                                GM_ADDR workspace,
                                const SinkhornTilingData *tilingData,
                                TPipe *tPipe);
    __aicore__ inline void Process();

  private:
    __aicore__ inline void CopyInX(int64_t offset);
    __aicore__ inline void CopyOut(int64_t offset);
    __aicore__ inline void TransposeXIn(LocalTensor<T> xLocal);
    __aicore__ inline void TransposeXOut();
    __aicore__ inline void InitialSoftmax();
    __aicore__ inline void ColNormalize(LocalTensor<uint8_t> calReduceTensor);
    __aicore__ inline void RowNormalize(LocalTensor<uint8_t> calReduceTensor);
    __aicore__ inline void CopyOutNormOut(int64_t offset);
    __aicore__ inline void CopyOutSumOut(int64_t offset);

  private:
    TPipe *pipe_;
    GlobalTensor<T> xGm_;
    GlobalTensor<T> outputGm_;
    GlobalTensor<T> normOutGm_;
    GlobalTensor<T> sumOutGm_;

    TQue<QuePosition::VECIN, 1> xInQueue_;
    TQue<QuePosition::VECOUT, 1> outputQueue_;
    TQue<QuePosition::VECOUT, 2> normOutQueue_;
    TQue<QuePosition::VECOUT, 2> sumOutQueue_;
    TBuf<QuePosition::VECCALC> tmpBuf_, maxBuf_, sumBuf_, transposeBuf_; // 中间计算缓存

    int64_t outFlag_;
    float eps_;
    int64_t numIters_;

    int64_t totalLength_;
    int64_t n_;
    int64_t needCoreNum_;
    int64_t tAlign_;

    // 核间切分
    int64_t perCoreElements_;
    int64_t lastCoreElements_;
    int64_t blockIdx_;

    // 核内切分
    int64_t perCoreLoops_;
    int64_t perCorePerLoopElements_;
    int64_t perCoreLastLoopElements_;
    int64_t lastCoreLoops_;
    int64_t lastCorePerLoopElements_;
    int64_t lastCoreLastLoopElements_;

    // 当前核的tiling策略
    int64_t currentCoreElements_;
    int64_t currentCoreloops_;
    int64_t currentCorePerLoopElements_;
    int64_t currentCoreLastLoopElements_;

    int64_t currentLoopElements_;
};

template <typename T>
__aicore__ inline void SinkhornGeneralized<T>::Init(GM_ADDR x,
                                                    GM_ADDR output,
                                                    GM_ADDR normOut,
                                                    GM_ADDR sumOut,
                                                    GM_ADDR workspace,
                                                    const SinkhornTilingData *tilingData,
                                                    TPipe *tPipe)
{
    pipe_ = tPipe;

    // Get tiling data
    outFlag_ = tilingData->outFlag;
    eps_ = tilingData->eps;
    numIters_ = tilingData->numIters;
    totalLength_ = tilingData->totalLength;
    n_ = tilingData->nNum;

    needCoreNum_ = tilingData->needCoreNum;
    perCoreElements_ = tilingData->perCoreElements;
    lastCoreElements_ = tilingData->lastCoreElements;
    perCoreLoops_ = tilingData->perCoreLoops;
    perCorePerLoopElements_ = tilingData->perCorePerLoopElements;
    perCoreLastLoopElements_ = tilingData->perCoreLastLoopElements;
    lastCoreLoops_ = tilingData->lastCoreLoops;
    lastCorePerLoopElements_ = tilingData->lastCorePerLoopElements;
    lastCoreLastLoopElements_ = tilingData->lastCoreLastLoopElements;

    blockIdx_ = GetBlockIdx();
    currentCoreElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreElements_ : lastCoreElements_;
    currentCoreloops_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreLoops_ : lastCoreLoops_;
    currentCorePerLoopElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCorePerLoopElements_ : lastCorePerLoopElements_;
    currentCoreLastLoopElements_ =
        (blockIdx_ < needCoreNum_ - 1) ? perCoreLastLoopElements_ : lastCoreLastLoopElements_;

    tAlign_ = Align(perCorePerLoopElements_, sizeof(float)); // 32B对齐

    // Set global tensors
    int64_t Offset = blockIdx_ * perCoreElements_ * n_ * n_;
    xGm_.SetGlobalBuffer((__gm__ T *)x + Offset, currentCoreElements_ * n_ * n_);
    outputGm_.SetGlobalBuffer((__gm__ T *)output + Offset, currentCoreElements_ * n_ * n_);
    normOutGm_.SetGlobalBuffer((__gm__ T *)normOut);
    sumOutGm_.SetGlobalBuffer((__gm__ T *)sumOut);

    // Initialize pipe (placeholder)
    // (5 tnn + 4 tn) * 4 + 1024n B
    pipe_->InitBuffer(xInQueue_, 1, tAlign_ * n_ * n_ * sizeof(T)); // t * n * n
    pipe_->InitBuffer(outputQueue_, 1, tAlign_ * n_ * n_ * sizeof(T)); // t * n * n

    pipe_->InitBuffer(maxBuf_, tAlign_ * n_ * sizeof(T)); // t * n
    pipe_->InitBuffer(sumBuf_, tAlign_ * n_ * sizeof(T)); // t * n
    pipe_->InitBuffer(transposeBuf_, tAlign_ * n_ * n_ * sizeof(T)); // t * n * n
    pipe_->InitBuffer(tmpBuf_, (n_ * n_ * 2 + 1) * 16 * 32); // (2n*n+1) * 16 * 32 B

    if (outFlag_) {
        pipe_->InitBuffer(normOutQueue_, DOUBULE_BUFFER, tAlign_ * n_ * n_ * sizeof(T)); // 2 * t * n * n
        pipe_->InitBuffer(sumOutQueue_, DOUBULE_BUFFER, tAlign_ * n_ * sizeof(T)); // 2 * t * n
    }
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::Process()
{
    if (blockIdx_ >= needCoreNum_) {
        return;
    }
    // 一次归一化产生的normOut矩阵大小
    int64_t normOutBlockLen = n_ * n_ * totalLength_;
    // 一次归一化产生的sumOut矩阵大小
    int64_t sumOutBlockLen = n_ * totalLength_;

    // Main processing loop (placeholder)
    for (int i = 0; i < currentCoreloops_; ++i) {
        // 当前核当前loop处理的token数
        currentLoopElements_ =
            (i == currentCoreloops_ - 1) ? currentCoreLastLoopElements_ : currentCorePerLoopElements_;
        // 核内GM核内偏移, 初始化时已增加核间偏移
        int64_t offset = i * currentCorePerLoopElements_ * n_ * n_;
        // normOut与sumOut在GM上最后一个维度上t的偏移
        int64_t tOffset = blockIdx_ * perCoreElements_ + i * currentCorePerLoopElements_;
        int64_t normOffset = 0;
        int64_t sumOffset = 0;

        // 步骤1：数据拷入+转置
        CopyInX(offset);
        LocalTensor<T> xLocal = xInQueue_.DeQue<T>();
        TransposeXIn(xLocal);
        LocalTensor<uint8_t> calReduceTensor = xLocal.template ReinterpretCast<uint8_t>();
        // 步骤2：行初始归一化(softmax)
        InitialSoftmax();
        if (outFlag_) {
            normOffset = tOffset;
            CopyOutNormOut(normOffset);
        }

        // 步骤3：列初始归一化
        ColNormalize(calReduceTensor);
        if (outFlag_) {
            normOffset = normOutBlockLen + tOffset;
            sumOffset = sumOutBlockLen + tOffset;
            CopyOutNormOut(normOffset);
            CopyOutSumOut(sumOffset);
        }

        // 步骤4：迭代行列交替归一化
        for (uint32_t iter = 1; iter < numIters_; ++iter) {
            int64_t rowOffset = 2 * iter;
            int64_t colOffset = 2 * iter + 1;
            // 行归一化
            RowNormalize(calReduceTensor);
            if (outFlag_) {
                normOffset = rowOffset * normOutBlockLen + tOffset;
                sumOffset = rowOffset * sumOutBlockLen + tOffset;
                CopyOutNormOut(normOffset);
                CopyOutSumOut(sumOffset);
            }
            // 列归一化
            ColNormalize(calReduceTensor);
            if (outFlag_) {
                normOffset = colOffset * normOutBlockLen + tOffset;
                sumOffset = colOffset * sumOutBlockLen + tOffset;
                CopyOutNormOut(normOffset);
                CopyOutSumOut(sumOffset);
            }
        }
        xInQueue_.FreeTensor(xLocal);
        // 步骤5：转置+数据拷出
        TransposeXOut();
        CopyOut(offset);
    }
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyInX(int64_t offset)
{
    LocalTensor<T> xLocal = xInQueue_.AllocTensor<T>();

    DataCopyExtParams dataCopyParams{
        static_cast<uint16_t>(1), static_cast<uint32_t>(currentLoopElements_ * n_ * n_ * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> dataCopyPadParams{false, 0, 0, 0};
    DataCopyPad(xLocal, xGm_[offset], dataCopyParams, dataCopyPadParams);
    xInQueue_.EnQue(xLocal);
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::TransposeXIn(LocalTensor<T> xLocal)
{
    // [t, n, n] 转换为[n, n, t]

    LocalTensor<T> xTranspose = transposeBuf_.Get<T>();

    LocalTensor<uint8_t> sharedBuffer = tmpBuf_.Get<uint8_t>();

    TransposeParamsExt transposeParams;
    transposeParams.nSize = 1;
    transposeParams.cSize = n_ * n_;
    transposeParams.hSize = 1;
    transposeParams.wSize = tAlign_;
    transposeParams.transposeType = TransposeType::TRANSPOSE_NHWC2NCHW;
    Transpose(xTranspose, xLocal, sharedBuffer, transposeParams);
    PipeBarrier<PIPE_V>();
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::TransposeXOut()
{
    // [n, n, t] 转换为[t, n, n]
    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
    LocalTensor<T> xTranspose = outputQueue_.AllocTensor<T>();

    LocalTensor<uint8_t> sharedBuffer = tmpBuf_.Get<uint8_t>();

    TransposeParamsExt transposeParams;
    transposeParams.nSize = 1;
    transposeParams.cSize = n_ * n_;
    transposeParams.hSize = 1;
    transposeParams.wSize = tAlign_;
    transposeParams.transposeType = TransposeType::TRANSPOSE_NCHW2NHWC;
    Transpose(xTranspose, xLocal, sharedBuffer, transposeParams);

    PipeBarrier<PIPE_V>();
    outputQueue_.EnQue(xTranspose);
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::InitialSoftmax()
{
    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
    LocalTensor<T> maxLocal = maxBuf_.Get<T>();
    LocalTensor<T> sumLocal = sumBuf_.Get<T>();
    LocalTensor<T> tmpLocal = tmpBuf_.Get<T>();
    int64_t nt = tAlign_ * n_;
    Duplicate(sumLocal, (T)(0), nt);
    PipeBarrier<PIPE_V>();
    for (uint32_t i = 0; i < n_; ++i) {
        // 对第i列的所有行j（j=0到N-1），找到每个批次的最大值
        uint32_t colOffset = i * n_ * tAlign_;
        uint32_t colMaxSumOffset = i * tAlign_;

        // 初始化最大值为第一行的值
        Max(maxLocal[colMaxSumOffset], xLocal[colOffset], xLocal[colOffset + tAlign_], tAlign_);
        PipeBarrier<PIPE_V>();
        // 遍历剩余行，更新最大值
        for (uint32_t j = 2; j < n_; ++j) {
            uint32_t rowOffset = colOffset + j * tAlign_;
            // 使用Max函数进行向量化最大值计算
            Max(maxLocal[colMaxSumOffset], maxLocal[colMaxSumOffset], xLocal[rowOffset], tAlign_);
        }

        for (uint32_t j = 0; j < n_; ++j) {
            uint32_t rowOffset = colOffset + j * tAlign_;
            // 计算 x - max
            Sub(tmpLocal, xLocal[rowOffset], maxLocal[colMaxSumOffset], tAlign_);
            PipeBarrier<PIPE_V>();
            // 计算 exp(x - max)
            Exp(tmpLocal, tmpLocal, tAlign_);
            PipeBarrier<PIPE_V>();
            // 累加到和
            Add(sumLocal[colMaxSumOffset], sumLocal[colMaxSumOffset], tmpLocal, tAlign_);
            // 将exp值写回数据
            DataCopy(xLocal[rowOffset], tmpLocal, tAlign_);
        }

        // 对第i列的所有行j，计算 exp / (sum + eps)
        for (uint32_t j = 0; j < n_; ++j) {
            uint32_t rowOffset = colOffset + j * tAlign_;
            Div(xLocal[rowOffset], xLocal[rowOffset], sumLocal[colMaxSumOffset], tAlign_);
        }
    }
    PipeBarrier<PIPE_V>();
    if (outFlag_) {
        LocalTensor<T> normLocal = normOutQueue_.AllocTensor<T>();
        DataCopy(normLocal, xLocal, tAlign_ * n_ * n_);
        normOutQueue_.EnQue(normLocal);
    }
    PipeBarrier<PIPE_V>();
    Adds(xLocal, xLocal, eps_, n_ * n_ * tAlign_);
    PipeBarrier<PIPE_V>();
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::ColNormalize(LocalTensor<uint8_t> calReduceTensor)
{
    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
    LocalTensor<T> sumLocal = sumBuf_.Get<T>();
    int64_t nt = tAlign_ * n_;

    uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_ * n_)};
    AscendC::ReduceSum<float, Pattern::Reduce::RA, false>(sumLocal, xLocal, calReduceTensor, shape, true);
    PipeBarrier<PIPE_V>();
    Adds(sumLocal, sumLocal, eps_, nt);
    PipeBarrier<PIPE_V>();
    for (uint32_t i = 0; i < n_; ++i) {
        Div(xLocal[i * nt], xLocal[i * nt], sumLocal, nt);
    }
    PipeBarrier<PIPE_V>();
    if (outFlag_) {
        LocalTensor<T> normLocal = normOutQueue_.AllocTensor<T>();
        LocalTensor<T> sumOutLocal = sumOutQueue_.AllocTensor<T>();
        DataCopy(normLocal, xLocal, tAlign_ * n_ * n_);
        DataCopy(sumOutLocal, sumLocal, tAlign_ * n_);
        normOutQueue_.EnQue(normLocal);
        sumOutQueue_.EnQue(sumOutLocal);
    }
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::RowNormalize(LocalTensor<uint8_t> calReduceTensor)
{
    LocalTensor<T> xLocal = transposeBuf_.Get<T>();
    LocalTensor<T> sumLocal = sumBuf_.Get<T>();
    int64_t nt = tAlign_ * n_;

    for (uint32_t i = 0; i < n_; ++i) {
        uint32_t colMaxSumOffset = i * tAlign_;
        uint32_t rowOffset = i * n_ * tAlign_;
        uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_)};

        ReduceSum<float, Pattern::Reduce::RA, false>(
            sumLocal[colMaxSumOffset], xLocal[rowOffset], calReduceTensor, shape, true);
        // 遍历所有列，累加第i行的值
        PipeBarrier<PIPE_V>();
        Adds(sumLocal[colMaxSumOffset], sumLocal[colMaxSumOffset], eps_, tAlign_);
        PipeBarrier<PIPE_V>();
        // 对第i行的所有列j，计算 value / (sum + eps)
        for (uint32_t j = 0; j < n_; ++j) {
            uint32_t colOffset = rowOffset + j * tAlign_;
            // value / (sum + eps)
            Div(xLocal[colOffset], xLocal[colOffset], sumLocal[colMaxSumOffset], tAlign_);
        }
    }
    PipeBarrier<PIPE_V>();
    if (outFlag_) {
        LocalTensor<T> normLocal = normOutQueue_.AllocTensor<T>();
        LocalTensor<T> sumOutLocal = sumOutQueue_.AllocTensor<T>();
        DataCopy(normLocal, xLocal, tAlign_ * n_ * n_);
        DataCopy(sumOutLocal, sumLocal, tAlign_ * n_);
        normOutQueue_.EnQue(normLocal);
        sumOutQueue_.EnQue(sumOutLocal);
    }
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyOutNormOut(int64_t normOffset)
{
    // srcStride，前一个数据块的尾与后一个数据块的头， GM上单位为字节
    // dstStride, 前一个数据块的尾与后一个数据块的头， UB上单位为32B
    LocalTensor<T> normLocal = normOutQueue_.DeQue<T>();

    uint16_t blockCount = static_cast<uint16_t>(n_ * n_);
    uint32_t blockLen = static_cast<uint32_t>(currentLoopElements_ * sizeof(T));
    uint32_t srcStride = static_cast<uint32_t>((tAlign_ - currentLoopElements_) * sizeof(T) / BLOCK_BYTES);
    uint32_t dstStride = static_cast<uint32_t>((totalLength_ - currentLoopElements_) * sizeof(T));
    DataCopyExtParams dataCopyParams{blockCount, blockLen, srcStride, dstStride, 0};

    DataCopyPad(normOutGm_[normOffset], normLocal, dataCopyParams);
    normOutQueue_.FreeTensor(normLocal);
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyOutSumOut(int64_t sumOffset)
{
    LocalTensor<T> sumLocal = sumOutQueue_.DeQue<T>();
    uint16_t blockCount = static_cast<uint16_t>(n_);
    uint32_t blockLen = static_cast<uint32_t>(currentLoopElements_ * sizeof(T));
    uint32_t srcStride = static_cast<uint32_t>((tAlign_ - currentLoopElements_) * sizeof(T) / BLOCK_BYTES);
    uint32_t dstStride = static_cast<uint32_t>((totalLength_ - currentLoopElements_) * sizeof(T));
    DataCopyExtParams dataCopyParams{blockCount, blockLen, srcStride, dstStride, 0};

    DataCopyPad(sumOutGm_[sumOffset], sumLocal, dataCopyParams);
    sumOutQueue_.FreeTensor(sumLocal);
}

template <typename T> __aicore__ inline void SinkhornGeneralized<T>::CopyOut(int64_t offset)
{
    LocalTensor<T> xLocal = outputQueue_.DeQue<T>();
    DataCopyExtParams copyParams{
        static_cast<uint16_t>(1), static_cast<uint32_t>(currentLoopElements_ * n_ * n_ * sizeof(T)), 0, 0, 0};
    DataCopyPad(outputGm_[offset], xLocal, copyParams);
    outputQueue_.FreeTensor(xLocal);
}

} // namespace ManifoldConstrainedHyperConnectionSinkhornEnhance

#endif // SINKHORN_GENERALIZED_H

