using namespace ge;

namespace ops {
// INPUT
constexpr uint32_t INITIAL_STATE_INPUT_INDEX = 0;
constexpr uint32_t VALUE_INPUT_INDEX = 2;

// OUTPUT
constexpr uint32_t INITIAL_STATE_OUTPUT_INDEX = 0;
constexpr uint32_t ATTN_INTER_OUT_OUTPUT_INDEX = 1;
constexpr uint32_t V_NEW_OUT_OUTPUT_INDEX = 2;


ge::graphStatus InferShape_Sinkhorn(gert::InferShapeContext* context)
{
    OPS_LOG_I(context->GetNodeName(), "Enter InferShape impl.");

    OPS_ERR_IF(SetShapeDim(context) != GRAPH_SUCCESS,
        OPS_LOG_E(context->GetNodeName(), "InferShape failed!"),
        return ge::GRAPH_FAILED
    );

    OPS_LOG_I(context->GetNodeName(), "InferShape end.");
    return GRAPH_SUCCESS;
}

ge::graphStatus InferDataType_Sinkhorn(gert::InferDataTypeContext* context)
{
    OPS_LOG_I(context->GetNodeName(), "Enter InferDataType impl.");

    auto initialStateInputDataType = context->GetRequiredInputDataType(INITIAL_STATE_INPUT_INDEX);
    auto valueDataType = context->GetRequiredInputDataType(VALUE_INPUT_INDEX);

    context->SetOutputDataType(INITIAL_STATE_OUTPUT_INDEX, initialStateInputDataType);
    context->SetOutputDataType(ATTN_INTER_OUT_OUTPUT_INDEX, valueDataType);
    context->SetOutputDataType(V_NEW_OUT_OUTPUT_INDEX, valueDataType);

    OPS_LOG_I(context->GetNodeName(), "InferDataType end.");
    return GRAPH_SUCCESS;
}

