45	    __aicore__ inline void CopyInX(int64_t idxT, int64_t sizeT);
46	    __aicore__ inline void CopyOut(int64_t idxT, int64_t sizeT);
47	
48	    // 返回实际 n 值：N>0 时返回编译时常量，N==0 时返回运行时 n_
49	    __aicore__ inline int64_t GetN() const
