63	    TQue<QuePosition::VECOUT, 2> outputQueue_;
64	    TBuf<QuePosition::VECCALC> sumBuf_;
65	    TBuf<QuePosition::VECCALC> tmpBuf_;
66	
67	    float   eps_;
68	    int64_t numIters_;
