89	    perCoreElements_         = tilingData->perCoreElements;
90	    lastCoreElements_        = tilingData->lastCoreElements;
91	    perCorePerLoopElements_  = tilingData->perCorePerLoopElements;
92	
93	    blockIdx_            = GetBlockIdx();
94	    currentCoreElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreElements_ : lastCoreElements_;
95	
96	    // 从 TilingData 读取预计算的 reduceMask
97	    reduceMask_ = tilingData->reduceMask;
98	
99	    int64_t gmOffset = blockIdx_ * perCoreElements_ * GetN() * GetN();
100	    xGm_.SetGlobalBuffer((__gm__ T *)x      + gmOffset, currentCoreElements_ * GetN() * GetN());
