104	    int64_t slotSize = perCorePerLoopElements_ * GetN() * INFER_ALIGN_N * sizeof(T);
105	    pipe_->InitBuffer(xInQueue_,    2, slotSize);
106	    pipe_->InitBuffer(outputQueue_, 2, slotSize);
107	    pipe_->InitBuffer(sumBuf_,      slotSize);
108	    pipe_->InitBuffer(tmpBuf_,      slotSize);
