 * \brief Inference kernel template (out_flag=0): DataCopyPad layout [n,t,ALIGN_N], no Transpose
 */
#ifndef SINKHORN_GENERALIZED_INFER_H
#define SINKHORN_GENERALIZED_INFER_H
#include "kernel_operator.h"
#include "kernel_utils.h"
#include "kernel_tiling/kernel_tiling.h"

namespace ManifoldConstrainedHyperConnectionSinkhornEnhanceInfer {
using namespace AscendC;

constexpr int64_t INFER_BLOCK_BYTES    = 32;
constexpr int64_t INFER_BLOCK_NUM      = 8;
constexpr int64_t INFER_REPEAT_ELEMS   = INFER_BLOCK_BYTES * INFER_BLOCK_NUM / sizeof(float); // 64
constexpr int64_t INFER_ALIGN_N        = 8;   // 每行 pad 到 8 个 float，恰好 1 个 32B datablock

// CopyIn/CopyOut 分支阈值：
//   sizeT >  NLOOP_THRESHOLD → N-loop（N次调用，每次 blockCount=sizeT）
//   sizeT <= NLOOP_THRESHOLD → sizeT-loop（sizeT次调用，每次 blockCount=N）
constexpr uint32_t NLOOP_THRESHOLD     = 4;

// N=0：运行时回退（n_ 由 tilingData->nNum 决定）
// N>0：编译时已知 n 值，启用 if constexpr 分支消除与循环展开
template <typename T, int64_t N = 0>
class SinkhornInferGeneralized {
public:
    __aicore__ inline SinkhornInferGeneralized(){};
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
                                GM_ADDR workspace, const SinkhornTilingData *tilingData, TPipe *tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyInX(int64_t idxT, int64_t sizeT);
    __aicore__ inline void CopyOut(int64_t idxT, int64_t sizeT);

    // 返回实际 n 值：N>0 时返回编译时常量，N==0 时返回运行时 n_
    __aicore__ inline int64_t GetN() const
    {
        if constexpr (N > 0) {
            return N;
        } else {
            return n_;
        }
    }

    TPipe *pipe_;
    GlobalTensor<T> xGm_;
    GlobalTensor<T> outputGm_;

    TQue<QuePosition::VECIN,  2> xInQueue_;
    TQue<QuePosition::VECOUT, 2> outputQueue_;
    TBuf<QuePosition::VECCALC> sumBuf_;
    TBuf<QuePosition::VECCALC> tmpBuf_;

    float   eps_;
    int64_t numIters_;
    int64_t n_;  // 仅 N==0 时有意义；N>0 时 GetN() 返回编译时常量
    int64_t needCoreNum_;
    int64_t perCoreElements_;
    int64_t lastCoreElements_;
    int64_t perCorePerLoopElements_;
    int64_t blockIdx_;
    int64_t currentCoreElements_;
    uint64_t reduceMask_;  // 预计算的 BlockReduce mask
};

template <typename T, int64_t N>
__aicore__ inline void SinkhornInferGeneralized<T, N>::Init(
    GM_ADDR x, GM_ADDR output, GM_ADDR workspace,
    const SinkhornTilingData *tilingData, TPipe *tPipe)
{
    pipe_                    = tPipe;
    eps_                     = tilingData->eps;
    numIters_                = tilingData->numIters;
    n_                       = tilingData->nNum;
    needCoreNum_             = tilingData->needCoreNum;
    perCoreElements_         = tilingData->perCoreElements;
    lastCoreElements_        = tilingData->lastCoreElements;
    perCorePerLoopElements_  = tilingData->perCorePerLoopElements;

    blockIdx_            = GetBlockIdx();
    currentCoreElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreElements_ : lastCoreElements_;

    // 从 TilingData 读取预计算的 reduceMask
    reduceMask_ = tilingData->reduceMask;

    int64_t gmOffset = blockIdx_ * perCoreElements_ * GetN() * GetN();
    xGm_.SetGlobalBuffer((__gm__ T *)x      + gmOffset, currentCoreElements_ * GetN() * GetN());
    outputGm_.SetGlobalBuffer((__gm__ T *)output + gmOffset, currentCoreElements_ * GetN() * GetN());

    // 6 个 buffer 槽，与 tiling CalTAlign 中 denominator = 6*ALIGN_N*n*dtype 对应
    int64_t slotSize = perCorePerLoopElements_ * GetN() * INFER_ALIGN_N * sizeof(T);
    pipe_->InitBuffer(xInQueue_,    2, slotSize);
    pipe_->InitBuffer(outputQueue_, 2, slotSize);
    pipe_->InitBuffer(sumBuf_,      slotSize);
    pipe_->InitBuffer(tmpBuf_,      slotSize);
}

